 \"sync\"
 \"strings\"
 \"sort\"
 \"strconv\"
 \"net/http\"

 \"github.com/labstack/echo/v4\"
)

type streamActivity struct {
 comments []LivecommentModel
 reactions []ReactionModel
 words []NGWord
 reports []LivecommentReportModel
 viewers map[int64]int64
}
var activityMu sync.RWMutex
var activities map[int64]*streamActivity
var commentByID map[int64]LivecommentModel
var writers [256]sync.Mutex

func lockStream(id int64)func(){lock:=&writers[uint64(id)%uint64(len(writers))];lock.Lock();return lock.Unlock}
func activity(id int64)*streamActivity{
 a:=activities[id];if a==nil{a=&streamActivity{viewers:map[int64]int64{}};activities[id]=a};return a
}
func loadActivity()error{
 activityMu.Lock();defer activityMu.Unlock()
 activities=map[int64]*streamActivity{};commentByID=map[int64]LivecommentModel{}
 var comments []struct{ LivecommentModel; Hidden bool }
 if err:=dbConn.Select(&comments,\"SELECT *,hidden FROM livecomments ORDER BY created_at,id\");err"'!=nil{return err}
 for _,row:=range comments {m:=row.LivecommentModel;commentByID[m.ID]=m;if !row.Hidden{a:=activity(m.LivestreamID);a.comments=append(a.comments,m)}}
 var reactions []ReactionModel
 if err:=dbConn.Select(&reactions,"SELECT * FROM reactions ORDER BY created_at,id");err!=nil{return err}
 for _,r:=range reactions{a:=activity(r.LivestreamID);a.reactions=append(a.reactions,r)}
 var words []NGWord
 if err:=dbConn.Select(&words,"SELECT * FROM ng_words ORDER BY created_at,id");err!=nil{return err}
 for _,r:=range words{a:=activity(r.LivestreamID);a.words=append(a.words,r)}
 var reports []LivecommentReportModel
 if err:=dbConn.Select(&reports,"SELECT * FROM livecomment_reports ORDER BY id");err!=nil{return err}
 for _,r:=range reports{a:=activity(r.LivestreamID);a.reports=append(a.reports,r)}
 var viewers []struct{Stream,Viewer,N int64}
 if err:=dbConn.Select(&viewers,"SELECT livestream_id AS stream,user_id AS viewer,COUNT(*) AS n FROM livestream_viewers_history GROUP BY livestream_id,user_id");err!=nil{return err}
 for _,v:=range viewers{activity(v.Stream).viewers[v.Viewer]=v.N}
 return nil
}
func pageSize(c echo.Context,n int)(int,error){
 if limit:=c.QueryParam("limit");limit!=""{l,err:=strconv.Atoi(limit);if err!=nil||l<0{return 0,echo.NewHTTPError(http.StatusBadRequest,"invalid limit")};if l<n{return l,nil}}
 return n,nil
}
func visibleAfterModeration(rows []LivecommentModel,word string)[]LivecommentModel{
