}
func rankedUser(id int64)UserStatistics{
 catalogMu.RLock();defer catalogMu.RUnlock();activityMu.RLock();defer activityMu.RUnlock()
 scores:=map[int64]int64{};emojis:=map[string]int{}
 stats:=UserStatistics{Rank:1}
 for sid,a:=range activities{owner:=catalog.streams[sid].Owner.ID;score:=int64(len(a.reactions));for _,c:=range a.comments{score+=c.Tip;if owner==id{stats.TotalTip+=c.Tip}}
 scores[owner]+=score;if owner!=id{continue};stats.TotalLivecomments+=int64(len(a.comments));stats.TotalReactions+=int64(len(a.reactions));for _,r:=range a.reactions{emojis[r.EmojiName]++};for _,n:=range a.viewers{stats.ViewersCount+=n}}
 for uid,u:=range catalog.users{if scores[uid]>scores[id]||(scores[uid]==scores[id] && u.Name>catalog.users[id].Name){stats.Rank++}}
 for emoji,n:=range emojis{if n>emojis[stats.FavoriteEmoji]||(n==emojis[stats.FavoriteEmoji]&&emoji>stats.FavoriteEmoji){stats.FavoriteEmoji=emoji}}
 return stats
}
func rankedStream(id int64)LivestreamStatistics{
 catalogMu.RLock();defer catalogMu.RUnlock();activityMu.RLock();defer activityMu.RUnlock()
 scores:=make(map[int64]int64,len(activities));stats:=LivestreamStatistics{Rank:1}
 for sid,a:=range activities{score:=int64(len(a.reactions));for _,c:=range a.comments{score+=c.Tip;if sid==id&&c.Tip>stats.MaxTip{stats.MaxTip=c.Tip}};scores[sid]=score;if sid==id{stats.TotalReports=int64(len(a.reports));stats.TotalReactions=int64(len(a.reactions));for _,n:=range a.viewers{stats.ViewersCount+=n}}}
 for sid:=range catalog.streams{if scores[sid]>scores[id]||(scores[sid]==scores[id]&&sid>id){stats.Rank++}}
 return stats
}

func newestWords(id,owner int64)[]NGWord{
 activityMu.RLock();defer activityMu.RUnlock();result:=[]NGWord{}
 if a:=activities[id];a!=nil{for _,word:=range a.words{if word.UserID==owner{result=append(result,word)}}}
 sort.SliceStable(result,func(i,j int)bool{if result[i].CreatedAt==result[j].CreatedAt{return result[i].ID>result[j].ID};return result[i].CreatedAt>result[j].CreatedAt});return result
}
